1	const { LRUCache } = require('lru-cache')
2	const Logger = require('../Logger')
3	const Database = require('../Database')
4	
5	class ApiCacheManager {
6	  defaultCacheOptions = { max: 1000, maxSize: 10 * 1000 * 1000, sizeCalculation: (item) => item.body.length + JSON.stringify(item.headers).length }
7	  defaultTtlOptions = { ttl: 30 * 60 * 1000 }
8	  highChurnModels = new Set(['session', 'mediaProgress', 'playbackSession', 'device'])
9	  modelsInvalidatingPersonalized = new Set(['mediaProgress'])
10	  modelsInvalidatingMe = new Set(['session', 'mediaProgress', 'playbackSession', 'device'])
11	
12	  constructor(cache = new LRUCache(this.defaultCacheOptions), ttlOptions = this.defaultTtlOptions) {
13	    this.cache = cache
14	    this.ttlOptions = ttlOptions
15	  }
16	
17	  init(database = Database) {
18	    let hooks = ['afterCreate', 'afterUpdate', 'afterDestroy', 'afterBulkCreate', 'afterBulkUpdate', 'afterBulkDestroy', 'afterUpsert']
19	    hooks.forEach((hook) => database.sequelize.addHook(hook, (model) => this.clear(model, hook)))
20	  }
21	
22	  getModelName(model) {
23	    if (typeof model?.name === 'string') return model.name
24	    if (typeof model?.model?.name === 'string') return model.model.name
25	    if (typeof model?.constructor?.name === 'string' && model.constructor.name !== 'Object') return model.constructor.name
26	    return 'unknown'
27	  }
28	
29	  clearByUrlPattern(urlPattern) {
30	    let removed = 0
31	    for (const key of this.cache.keys()) {
32	      try {
33	        const parsed = JSON.parse(key)
34	        if (typeof parsed?.url === 'string' && urlPattern.test(parsed.url)) {
35	          if (this.cache.delete(key)) removed++
36	        }
37	      } catch {
38	        if (this.cache.delete(key)) removed++
39	      }
40	    }
41	    return removed
42	  }
43	
44	  clearUserProgressSlices(modelName, hook) {
45	    let removedPersonalized = 0
46	    let removedRecentEpisodes = 0
47	    if (this.modelsInvalidatingPersonalized.has(modelName)) {
48	      removedPersonalized = this.clearByUrlPattern(/^\/libraries\/[^/]+\/personalized/)
49	      removedRecentEpisodes = this.clearByUrlPattern(/^\/libraries\/[^/]+\/recent-episodes/)
50	    }
51	    const removedMe = this.modelsInvalidatingMe.has(modelName) ? this.clearByUrlPattern(/^\/me(\/|\?|$)/) : 0
52	    Logger.debug(`[ApiCacheManager] ${modelName}.${hook}: cleared user-progress cache slices (personalized=${removedPersonalized}, recentEpisodes=${removedRecentEpisodes}, me=${removedMe})`)
53	  }
